using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using ProjectWait.M.Elevator;public static class InspectFaceParts {public static string Main(){var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var p=l.GetComponent<ElevatorCharacterPerformance>();var skin=p.faceRenderer;var mesh=p.normalFaceMesh;skin.sharedMesh=mesh;var baked=new Mesh();skin.BakeMesh(baked);var v=baked.vertices;var head=l.friend.GetComponentsInChildren<Transform>(true).First(t=>t.name=="head");var local=v.Select(x=>head.InverseTransformPoint(skin.transform.TransformPoint(x))).ToArray();var parent=Enumerable.Range(0,v.Length).ToArray();int Root(int i){while(parent[i]!=i){parent[i]=parent[parent[i]];i=parent[i];}return i;}void Union(int a,int b){a=Root(a);b=Root(b);if(a!=b)parent[b]=a;}var points=new Dictionary<Vector3Int,int>();for(int i=0;i<v.Length;i++){var q=new Vector3Int(Mathf.RoundToInt(v[i].x*100000),Mathf.RoundToInt(v[i].y*100000),Mathf.RoundToInt(v[i].z*100000));if(points.TryGetValue(q,out int other))Union(i,other);else points.Add(q,i);}var tri=mesh.triangles;for(int i=0;i<tri.Length;i+=3){Union(tri[i],tri[i+1]);Union(tri[i],tri[i+2]);}var result=Enumerable.Range(0,v.Length).GroupBy(Root).Select(g=>{var ids=g.ToArray();var b=new Bounds(local[ids[0]],Vector3.zero);foreach(var i in ids)b.Encapsulate(local[i]);return new{id=g.Key,count=ids.Length,centre=b.center.ToString("F5"),size=b.size.ToString("F5"),c=b.center,sz=b.size};}).Where(x=>x.c.y>-.02f&&x.c.y<.4f&&x.c.z>.12f).Select(x=>new{x.id,x.count,x.centre,x.size}).ToArray();UnityEngine.Object.DestroyImmediate(baked);var json=Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorCoping_20261030~/FaceParts.json",json);return json;}}